#!/usr/bin/env python3
# Generated by @ethlete/agent-rules — DO NOT EDIT. Run `npx ethlete-agents sync`.
"""PreToolUse hook: run a subagent on sonnet unless its call names a model.

A `Task` call that passes no `model` runs the subagent on the parent session's
model. A session led by an expensive model therefore spends that model on every
grep and every file read it delegates, which burns a usage limit in minutes for
work a small model does just as well.

So this hook rewrites or gates the tool call:

  * No `model` at all - allowed with `model: sonnet` filled in, and a short note
    that names the models to pick explicitly instead.
  * `model: fable` - the user is asked. Fable is the right pick for planning,
    design, cross-cutting review and leading other subagents, and the wrong pick
    for the twentieth mechanical lookup; only the user knows which this is.
  * Any other model - allowed silently.

Two cases are left alone, because the tool's `model` would change nothing:

  * `subagent_type: fork`, which always inherits the parent model.
  * An agent type whose own definition under `.claude/agents/` sets a model.

Every subagent start, whatever the decision, appends one JSON line to
`<git common dir>/ethlete/subagent-starts.jsonl`: time, session, HEAD, branch,
the model it will run on, effort, agent type, description, the prompt's head and
the file paths the prompt names. It lives inside `.git`, so it is never committed,
and HEAD plus the paths join it with later commits.

Can be disabled per machine via a gitignored ethlete-agents.config.local.json at
the repo root: {"disableHooks": true} or {"disableHooks": ["subagent-model-policy"]}.

Fail-safe: any error exits 0 with no output - the hook must never block work
because it could not read its own input.
"""

import json
import os
import re
import subprocess
import sys
from datetime import datetime, timezone

HOOK_NAME = "subagent-model-policy"
LOCAL_CONFIG_FILE = "ethlete-agents.config.local.json"

# The tool that spawns a subagent, under both names it has carried.
SUBAGENT_TOOLS = ("Task", "Agent")

DEFAULT_MODEL = "sonnet"

LOG_FILE = os.path.join("ethlete", "subagent-starts.jsonl")
PROMPT_HEAD_CHARS = 300
MAX_LOGGED_FILES = 50
FILE_PATH = re.compile(r"(?<![\w/.-])(?:\.?[\w@-][\w@.-]*/)+[\w@.-]*\.[A-Za-z0-9]{1,8}(?![\w/])")

POLICY = """This call passed no `model`, so the subagent runs on sonnet, the default. Name a model on the next \
call when the task fits another one:

- `haiku` - lookups and small, fully specified jobs: grep, find, read and summarize files or a CI log, run a command and report, a mechanical edit in named files.
- `sonnet` - scoped work with a clear target: a fix in a named file, a spec, a docs page, a lint cleanup, \
research that needs reasoning. Sonnet 5.5 is close to opus here and costs less.
- `opus` - hard work: a bug with no known cause, a change across many files, a review of a diff, and any task \
sonnet did not finish.
- `fable` - judgment-heavy work: planning, design, cross-cutting review, leading other subagents. The most \
expensive of the four, so choosing it asks the user first.

Effort follows the prompt, not a parameter: scope the prompt to one question, name what "done" is, and say \
"keep it brief" for a lookup. A subagent has the session's context budget on its own transcript and hands back \
at the critical tier, so size the prompt to one slice that fits; more work means a fresh subagent per slice. An agent type defined under `.claude/agents/` carries its own model and reasoning \
effort, so a call that names one needs no `model` of its own."""

FABLE_REASON = """This subagent would run on fable, the most expensive model. Approve it where the task is \
judgment-heavy - planning, design, cross-cutting review, or leading other subagents. Deny it for implementation \
(`model: "sonnet"` or `"opus"`) or for a lookup or a small, fully specified job (`model: "haiku"`), then repeat the call with that model."""


def agent_name(argv):
    """The --agent value, defaulting to claude — older registrations pass no flag."""
    for index, arg in enumerate(argv):
        if arg == "--agent" and index + 1 < len(argv):
            return argv[index + 1]
        if arg.startswith("--agent="):
            return arg.split("=", 1)[1]
    return "claude"


def repo_root(data):
    """Repo root: the env var the agent sets, else the script's own location, else the cwd.

    The script always lives at <root>/.<agent>/hooks/ethlete/subagent-model-policy.py, so
    walking four levels up works for any agent that has no project-dir variable of its own.
    """
    for variable in ("CLAUDE_PROJECT_DIR", "CODEX_PROJECT_DIR"):
        value = os.environ.get(variable)
        if value:
            return value
    here = os.path.abspath(__file__)
    derived = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(here))))
    if os.path.isfile(os.path.join(derived, LOCAL_CONFIG_FILE)):
        return derived
    cwd = data.get("cwd")
    return cwd if isinstance(cwd, str) and cwd else derived


def load_local_config(root):
    """Parsed ethlete-agents.config.local.json at the repo root, or {} if missing/unreadable."""
    if not root:
        return {}
    try:
        with open(os.path.join(root, LOCAL_CONFIG_FILE), encoding="utf-8") as f:
            config = json.load(f)
    except (OSError, ValueError, AttributeError):
        return {}
    return config if isinstance(config, dict) else {}


def disabled_locally(config):
    """True when the local config disables this hook (or all hooks) on this machine."""
    disabled = config.get("disableHooks")
    return disabled is True or (isinstance(disabled, list) and HOOK_NAME in disabled)


def definition_sets_model(root, subagent_type):
    """True when a project or user agent definition of that name declares its own model."""
    if not subagent_type:
        return False
    file_name = f"{subagent_type.split(':')[-1]}.md".lower()
    candidates = []
    for directory in (
        os.path.join(root or ".", ".claude", "agents"),
        os.path.join(os.path.expanduser("~"), ".claude", "agents"),
    ):
        try:
            entries = os.listdir(directory)
        except OSError:
            continue
        candidates += [os.path.join(directory, entry) for entry in entries if entry.lower() == file_name]
    for path in candidates:
        try:
            with open(path, encoding="utf-8") as f:
                head = f.read(4096)
        except OSError:
            continue
        for line in head.split("\n"):
            key, separator, value = line.partition(":")
            if separator and key.strip() == "model" and value.strip():
                return True
    return False


def decision_for(tool_input, root):
    """The (decision, reason, updated input or None) this call needs, or None when it may run untouched."""
    subagent_type = str(tool_input.get("subagent_type") or "").strip().lower()
    model = str(tool_input.get("model") or "").strip().lower()

    if "fable" in model:
        return "ask", FABLE_REASON, None
    if model:
        return None
    if subagent_type == "fork" or definition_sets_model(root, subagent_type):
        return None
    return "allow", POLICY, {**tool_input, "model": DEFAULT_MODEL}


def git(root, *args):
    result = subprocess.run(["git", "-C", root, *args], capture_output=True, text=True, timeout=3)
    return result.stdout.strip() if result.returncode == 0 else ""


def prompt_files(prompt):
    files = []
    for match in FILE_PATH.findall(prompt):
        path = match.split(":")[0]
        if path not in files:
            files.append(path)
    return files[:MAX_LOGGED_FILES]


def run_model(tool_input, outcome):
    """The model the subagent will run on, or how it is chosen when the call does not name one."""
    if outcome and outcome[2] is not None:
        return outcome[2].get("model")
    model = str(tool_input.get("model") or "").strip().lower()
    if model:
        return model
    subagent_type = str(tool_input.get("subagent_type") or "").strip().lower()
    return "inherit" if subagent_type == "fork" else "definition"


def log_start(data, tool_input, root, outcome):
    common_dir = git(root, "rev-parse", "--path-format=absolute", "--git-common-dir")
    if not common_dir:
        return
    prompt = str(tool_input.get("prompt") or "")
    entry = {
        "time": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "session": data.get("session_id"),
        "toolUseId": data.get("tool_use_id"),
        "head": git(root, "rev-parse", "HEAD"),
        "branch": git(root, "rev-parse", "--abbrev-ref", "HEAD"),
        "model": run_model(tool_input, outcome),
        "decision": outcome[0] if outcome else "untouched",
        "effort": tool_input.get("effort"),
        "subagentType": tool_input.get("subagent_type"),
        "description": tool_input.get("description"),
        "prompt": prompt[:PROMPT_HEAD_CHARS],
        "promptChars": len(prompt),
        "files": prompt_files(prompt),
    }
    path = os.path.join(common_dir, LOG_FILE)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "a", encoding="utf-8") as f:
        f.write(json.dumps(entry) + "\n")


def main():
    if agent_name(sys.argv[1:]) != "claude":
        return

    data = json.load(sys.stdin)

    if data.get("tool_name") not in SUBAGENT_TOOLS:
        return

    tool_input = data.get("tool_input")

    if not isinstance(tool_input, dict):
        return

    root = repo_root(data)

    if disabled_locally(load_local_config(root)):
        return

    outcome = decision_for(tool_input, root)

    try:
        log_start(data, tool_input, root, outcome)
    except Exception:
        pass

    if not outcome:
        return

    decision, reason, updated_input = outcome
    output = {
        "hookEventName": "PreToolUse",
        "permissionDecision": decision,
        "permissionDecisionReason": reason,
    }
    if updated_input is not None:
        output["updatedInput"] = updated_input
    print(json.dumps({"hookSpecificOutput": output}))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        pass
    sys.exit(0)
